y", "widget-id": "record_farmer_language_spoken", "widget-type": "display", "widget-label": "Language", "widget-readonly": true, "widget-required": false, "widget-data-path": "997676d3-7008-59f9-b23e-613ad79bbb08.farmer_language_spoken"}]}, {"panel-id": "vp_livestock_livestock_farmer_profile_section_04_3", "panel-orientation": "vertical", "widgets": [{"widget": "boolean", "widget-id": "record_farmer_disabled", "widget-type": "input", "widget-label": "Has a disability", "widget-readonly": true, "widget-required": false, "widget-data-path": "997676d3-7008-59f9-b23e-613ad79bbb08.farmer_disabled", "widget-data-format": {"allowUnset": true, "booleanControlType": "radio", "booleanRepresentation": "yes-no"}}, {"widget": "display", "widget-id": "record_farmer_disability_type", "widget-type": "display", "widget-label": "Disability type", "widget-readonly": true, "widget-required": false, "widget-data-path": "997676d3-7008-59f9-b23e-613ad79bbb08.farmer_disability_type"}]}]}]}'::jsonb,
